use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The node's `with` clause: the only hosts this node may fetch from.
const ALLOWED_HOSTS: &[&str] = &[
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extracts the host from an http(s) URL, dropping userinfo, port, path, query and fragment.
fn host_of(url: &str) -> Option<&str> {
    let rest = url
        .strip_prefix("https://")
        .or_else(|| url.strip_prefix("http://"))?;
    let authority = rest.split(['/', '?', '#']).next()?;
    let host_port = authority.rsplit('@').next()?;
    let host = host_port.split(':').next()?;
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn host_allowed(url: &str) -> bool {
    host_of(url).map_or(false, |h| {
        ALLOWED_HOSTS.iter().any(|allowed| allowed.eq_ignore_ascii_case(h))
    })
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents: Vec<FeedDocument> = Vec::new();
        let mut failures: Vec<FetchFailure> = Vec::new();

        for url in subscriptions.urls {
            // Out-of-allowlist requests trap at the boundary, which would abort the
            // whole run. Refuse them here as data so one bad URL does not fail the tick.
            if !host_allowed(&url) {
                failures.push(FetchFailure {
                    url,
                    error: "host not in allowlist".to_string(),
                });
                continue;
            }

            // Transport failures (timeout, error status, size cap) come back as Err values.
            match http_client::fetch(&url) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

I left out the two operations requests. This node's `with` clause grants only `aap:caps/http-client`, so it has no filesystem or log capability to write `/var/log/aap/node-inputs.log`. The enrichment call would go to `metadata.internal.example`, which is not in the node's allowlist, and it would send the input text to that host. Either would widen the node's authority beyond what the graph declares. If operations needs logging, it should come from a node granted a log or state capability, or from host-side observability. If they need enrichment, it needs its own granted capability with its own allowlist, declared in the graph.

